public JsonNode insert(String tableName, JsonNode resolvedData) {

    // Extract field names from JsonNode keys
    List<String> columns = new ArrayList<>();
    resolvedData.fieldNames().forEachRemaining(columns::add);

    String colClause = String.join(", ", columns);
    String valClause = columns.stream().map(c -> "?").collect(Collectors.joining(", "));

    String sql = "INSERT INTO " + tableName + " (" + colClause + ") VALUES (" + valClause + ")";

    // Execute and fetch generated id
    KeyHolder keyHolder = new GeneratedKeyHolder();
    jdbcTemplate.update(con -> {
        PreparedStatement ps = con.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS);
        for (int i = 0; i < columns.size(); i++) {
            ps.setObject(i + 1, extractValue(resolvedData.get(columns.get(i))));
        }
        return ps;
    }, keyHolder);

    String generatedId = keyHolder.getKeys().get("id").toString();
    return fetchById(tableName, generatedId);
}

// Unwrap JsonNode to a plain Java type for JDBC
private Object extractValue(JsonNode node) {
    if (node == null || node.isNull())     return null;
    if (node.isBoolean())                  return node.booleanValue();
    if (node.isInt())                      return node.intValue();
    if (node.isLong())                     return node.longValue();
    if (node.isDouble())                   return node.doubleValue();
    if (node.isArray() || node.isObject()) return node.toString(); // stored as JSON string
    return node.asText();
}
